{
  "a_sentences": [
    {
      "a_text": "Les travailleurs ont demandé le remboursement des montants retenus sur leurs salaires à titre de contribution de solidarité prévue par la CCT, subsidiairement la réduction de ces montants.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Selon un auteur de doctrine cité par les recourants, un litige sur la réduction de la contribution de solidarité ne relèverait pas du contrat de travail mais devrait être ouvert contre toutes les parties à la convention collective.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que le litige ressortissait au droit du travail et que le Tribunal des prud'hommes était compétent en vertu de l'art. 1 al. 1 let. a LTPH-GE.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La juridiction cantonale a considéré qu'il suffisait que le litige trouve sa source dans une relation de travail et que le fondement juridique de la prétention n'était pas déterminant.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que les demandes, dirigées contre l'employeur et portant sur les salaires, ne sont pas arbitraires à qualifier de litige découlant du droit du travail.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette les griefs de violation de l'art. 30 Cst., de l'art. 6 § 1 CEDH et de violation arbitraire du droit cantonal genevois.",
      "b_propositions": ["P6"]
    }
  ]
}
